	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		CreativeApproval
	 */
		public CreativeApproval createCreativeApproval( CreateCreativeApprovalCommand command ) {

		CreativeApproval entity = new CreativeApproval();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCreativeApprovalId( command.getCreativeApprovalId() );
            entity.setReviewer( command.getReviewer() );
            entity.setReviewedAt( command.getReviewedAt() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of CreativeApproval {0} ", entity.toString() );

		return entity;
	}

